include { BCFTOOLS_CONCAT } from 'nf-core/bcftools/concat'
include { BCFTOOLS_SORT   } from 'nf-core/bcftools/sort'
include { HTSLIB_BGZIPTABIX     } from 'nf-core/htslib/bgziptabix'

workflow VCF_GATHER_BCFTOOLS {
    take:
    ch_vcfs           // channel: [ meta, vcf, index, count ]
    arr_common_meta   // array: The name of the meta fields that should be used for grouping
    val_sort          // boolean: Whether or not the output file should be sorted !! Add the config when using sort !!

    main:

    // Check if arr_common_meta is an array or list
    if (!(arr_common_meta instanceof List || arr_common_meta instanceof Collection)) {
        error("ERROR: arr_common_meta should be an array or list, got ${arr_common_meta.getClass()}")
    }

    ch_concat_input = ch_vcfs
        .map { meta, vcf, index, count ->
            def missingKeys = arr_common_meta.findAll { key -> !(key in meta.keySet()) }
            if (missingKeys) {
                error("ERROR: Keys ${missingKeys} from arr_common_meta not found in meta. Available keys: ${meta.keySet()}")
            }
            def newMeta = arr_common_meta ?
                arr_common_meta.collectEntries { key -> [(key): meta[key]] } :
                meta
            [groupKey(newMeta, count), meta, vcf, index]
        }
        .groupTuple()
        .branch { key, metas, vcf, index ->
            def cleanedMetas = metas.collect { meta -> meta
                .findAll { k, _v -> !(k in arr_common_meta) }
                .toSorted() // sort inside each meta map
            }.sort { a, b -> a.toString() <=> b.toString() } // sort across meta maps
            def newMeta = arr_common_meta ? key.target + [metas: cleanedMetas] : metas[0]
            def out_tuple = [newMeta, vcf.sort(), index.sort()]

            one: vcf.size() == 1
                return out_tuple
            more: vcf.size() > 1
                return out_tuple
        }

    // Concatenate vcf with more than one record
    BCFTOOLS_CONCAT(ch_concat_input.more)

    ch_vcf_concat = ch_concat_input.one
        .map{ meta, vcf, _index -> [meta, vcf.get(0)] }
        .mix(BCFTOOLS_CONCAT.out.vcf)

    if (val_sort) {
        BCFTOOLS_SORT(ch_vcf_concat)
        ch_tabix_input = BCFTOOLS_SORT.out.vcf
    } else {
        ch_tabix_input = ch_vcf_concat
    }

    HTSLIB_BGZIPTABIX(
        ch_tabix_input.map { meta, vcf -> [meta, vcf, [], []] },
        "compress",
        true,
        "vcf"
    )

    ch_vcf_index = HTSLIB_BGZIPTABIX.out.output.join(HTSLIB_BGZIPTABIX.out.index)

    emit:
    vcf       = HTSLIB_BGZIPTABIX.out.output // channel: [ val(meta), [ vcf ] ]
    index     = HTSLIB_BGZIPTABIX.out.index  // channel: [ val(meta), [ tbi or csi ] ]
    vcf_index = ch_vcf_index                 // channel: [ val(meta), [ vcf ], [ tbi or csi ] ]
}

nextflow_workflow {

    name "Test Workflow VCF_GATHER_BCFTOOLS"
    script "../main.nf"
    config "./nextflow.config"

    workflow "VCF_GATHER_BCFTOOLS"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/vcf_gather_bcftools"
    tag "vcf_gather_bcftools"

    tag "bcftools"
    tag "bcftools/concat"
    tag "bcftools/sort"
    tag "htslib"
    tag "htslib/bgziptabix"

    test("homo_sapiens - [vcf, tbi] [vcf, tbi] - meta [] 2 - sample, key - true") {
        when {
            workflow {
                """
                input[0] = channel.of(
                    [
                        [id:'test_1', sample:'test', key: '1', other:'annotated'],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/gatk/haplotypecaller_calls/test2_haplotc.ann.vcf.gz', checkIfExists:true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/gatk/haplotypecaller_calls/test2_haplotc.ann.vcf.gz.tbi', checkIfExists:true),
                        2
                    ],
                    [
                        [id:'test_2', sample:'test', key: '1', other:'not_annotated'],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/gatk/haplotypecaller_calls/test2_haplotc.vcf.gz', checkIfExists:true),
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/gatk/haplotypecaller_calls/test2_haplotc.vcf.gz.tbi', checkIfExists:true),
                        2
                    ]
                )
                input[1] = ['sample', 'key']
                input[2] = true
                """
            }
        }
        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    workflow.out.vcf.collect{ [it[0], path(it[1]).vcf.variantsMD5, path(it[1]).vcf.summary] },
                    workflow.out.index.collect{ [it[0], file(it[1]).name] },
                ).match() }
            )
        }
    }

